SET NAMES utf8mb4;

-- crop_types 基础数据，若已有可保留 ON DUPLICATE KEY UPDATE
ON DUPLICATE KEY UPDATE crop_name=VALUES(crop_name), crop_name_en=VALUES(crop_name_en);

-- disease_knowledge 61 类病害知识库数据；disease_id 使用 1-61，对应模型 class_index 0-60 加 1
ON DUPLICATE KEY UPDATE
  disease_name=VALUES(disease_name),
  disease_name_en=VALUES(disease_name_en),
  crop_type=VALUES(crop_type),
  crop_type_id=VALUES(crop_type_id),
  severity_level=VALUES(severity_level),
  symptoms=VALUES(symptoms),
  solutions=VALUES(solutions),
  prevention_methods=VALUES(prevention_methods);
