INSERT INTO crop_types (crop_type_id, crop_name, crop_name_en) VALUES
  (1, '苹果', 'Apple'),
  (2, '樱桃', 'Cherry'),
  (3, '玉米', 'Corn'),
  (4, '葡萄', 'Grape'),
  (5, '柑桔', 'Citrus'),
  (6, '桃', 'Peach'),
  (7, '辣椒', 'Pepper'),
  (8, '马铃薯', 'Potato'),
  (9, '草莓', 'Strawberry'),
  (10, '番茄', 'Tomato')
INSERT INTO disease_knowledge (disease_id, disease_name, disease_name_en, crop_type, crop_type_id, severity_level, symptoms, solutions, prevention_methods) VALUES
  (1, '健康', 'Apple-Healthy', '苹果', 1, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (2, '黑星病一般', 'Apple_Scab general', '苹果', 1, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片或果面出现橄榄色至黑褐色绒状斑，病斑逐渐扩大并可能导致叶片畸形、早落或果面粗糙开裂。', '摘除重病叶和病果并集中处理；改善树冠通风透光；发病初期可按当地植保建议选用登记杀菌剂进行保护和治疗。', '冬季清除落叶病果，降低越冬菌源；雨季前加强预防性管理，避免树冠郁闭和长时间叶面潮湿。'),
  (3, '黑星病严重', 'Apple_Scab serious', '苹果', 1, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片或果面出现橄榄色至黑褐色绒状斑，病斑逐渐扩大并可能导致叶片畸形、早落或果面粗糙开裂。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除重病叶和病果并集中处理；改善树冠通风透光；发病初期可按当地植保建议选用登记杀菌剂进行保护和治疗。', '冬季清除落叶病果，降低越冬菌源；雨季前加强预防性管理，避免树冠郁闭和长时间叶面潮湿。'),
  (4, '灰斑病', 'Apple Frogeve Spot', '苹果', 1, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现灰白色至褐色圆形或近圆形斑点，中心颜色变浅，边缘较深，严重时病斑融合导致叶片枯黄。', '及时剪除病叶，减少病原积累；加强通风降湿；发病较重时按标签选用适合作物的保护性杀菌剂。', '合理修剪和控制氮肥用量，雨后及时排湿，避免叶片长期潮湿，减少病害反复发生。'),
  (5, '雪松锈病一般', 'Cedar Apple Rust general', '苹果', 1, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片正面出现黄橙色圆斑，后期叶背可见锈色突起或毛状结构，严重时叶片早落，树势减弱。', '清除病叶并减少与寄主植物混栽风险；发病初期结合修剪和通风管理，必要时按当地植保意见使用登记杀菌剂。', '避免果园附近保留高风险中间寄主，春季多雨时期加强巡查，早发现早处理。'),
  (6, '雪松锈病严重', 'Cedar Apple Rust serious', '苹果', 1, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片正面出现黄橙色圆斑，后期叶背可见锈色突起或毛状结构，严重时叶片早落，树势减弱。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除病叶并减少与寄主植物混栽风险；发病初期结合修剪和通风管理，必要时按当地植保意见使用登记杀菌剂。', '避免果园附近保留高风险中间寄主，春季多雨时期加强巡查，早发现早处理。'),
  (7, '健康', 'Cherry-Healthy', '樱桃', 2, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (8, '白粉病一般', 'Cherry_Powdery Midew general', '樱桃', 2, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、嫩梢或果面出现白色粉状霉层，叶片可能卷曲、变脆，新梢生长受阻，严重时影响开花和结果。', '摘除重病叶和病梢；加强通风透光，降低湿度；可选用对白粉病有效且登记适用的药剂轮换防治。', '避免偏施氮肥和过密种植；保持植株通风，发病季节加强早期监测并及时处理初发病株。'),
  (9, '白粉病严重', 'Cherry_Powdery Midew serious', '樱桃', 2, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、嫩梢或果面出现白色粉状霉层，叶片可能卷曲、变脆，新梢生长受阻，严重时影响开花和结果。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除重病叶和病梢；加强通风透光，降低湿度；可选用对白粉病有效且登记适用的药剂轮换防治。', '避免偏施氮肥和过密种植；保持植株通风，发病季节加强早期监测并及时处理初发病株。'),
  (10, '健康', 'Corn-Healthy', '玉米', 3, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (11, '灰斑病一般', 'Cercospora zeaemaydis general', '玉米', 3, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。玉米叶片出现长条形灰褐色病斑，多受叶脉限制呈矩形，湿度大时病斑扩大并导致叶片提前枯死。', '发病叶片较多时应减少田间湿度，及时清除残体；结合当地植保建议选用适宜杀菌剂进行防控。', '选用抗病品种，实行轮作，收获后处理病残体，避免连作和高密度种植造成病害加重。'),
  (12, '灰斑病严重', 'Cercospora zeaemaydis serious', '玉米', 3, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。玉米叶片出现长条形灰褐色病斑，多受叶脉限制呈矩形，湿度大时病斑扩大并导致叶片提前枯死。', '建议优先处理重病叶、病果或病株，避免继续扩散。发病叶片较多时应减少田间湿度，及时清除残体；结合当地植保建议选用适宜杀菌剂进行防控。', '选用抗病品种，实行轮作，收获后处理病残体，避免连作和高密度种植造成病害加重。'),
  (13, '锈病一般', 'Puccinia polysora general', '玉米', 3, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片表面出现黄褐色至铁锈色小疱斑，破裂后散出粉状孢子，严重时叶片枯黄、光合作用下降。', '早期发现后及时评估发生面积，重病田块可按当地植保建议使用登记杀菌剂；减少氮肥过量并改善田间通风。', '选用抗病品种，合理密植，避免长期高湿环境，及时清理病残体以降低再侵染。'),
  (14, '锈病严重', 'Puccinia polysora serious', '玉米', 3, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片表面出现黄褐色至铁锈色小疱斑，破裂后散出粉状孢子，严重时叶片枯黄、光合作用下降。', '建议优先处理重病叶、病果或病株，避免继续扩散。早期发现后及时评估发生面积，重病田块可按当地植保建议使用登记杀菌剂；减少氮肥过量并改善田间通风。', '选用抗病品种，合理密植，避免长期高湿环境，及时清理病残体以降低再侵染。'),
  (15, '叶斑病一般', 'Corn Curvularia leaf spot fungus general', '玉米', 3, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现褐色或灰褐色小斑，常伴有黄晕，病斑可逐渐扩大融合，导致叶片枯斑和早衰。', '清除明显病叶，改善通风排湿；发病初期可依据当地植保推荐进行药剂防治，并注意轮换作用机制。', '实行轮作和清洁田园，控制种植密度，避免叶面长时间结露或积水。'),
  (16, '叶斑病严重', 'Corn Curvularia leaf spot fungus serious', '玉米', 3, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现褐色或灰褐色小斑，常伴有黄晕，病斑可逐渐扩大融合，导致叶片枯斑和早衰。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除明显病叶，改善通风排湿；发病初期可依据当地植保推荐进行药剂防治，并注意轮换作用机制。', '实行轮作和清洁田园，控制种植密度，避免叶面长时间结露或积水。'),
  (17, '花叶病毒病', 'Maize dwarf mosaic virus', '玉米', 3, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现黄绿相间的花叶、斑驳或畸形，新叶变小，植株可能矮化，严重时影响产量和品质。', '病毒病无特效治疗药剂。发现重病株应及时拔除或隔离，重点控制蚜虫、粉虱等传播媒介，并加强田间卫生。', '选用健康种苗和抗病品种，防治传毒昆虫，工具消毒，避免接触传播和病株残体再传播。'),
  (18, '健康', 'Grape-Healthy', '葡萄', 4, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (19, '黑腐病一般', 'Grape Black Rot Fungus general', '葡萄', 4, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现褐色圆斑并带黑色小点，果实可形成黑褐色凹陷斑，后期果粒干缩成僵果。', '剪除病叶、病穗和僵果并带出园外处理；改善架面通风；雨季结合当地建议进行保护性防治。', '冬剪时清除病残体，保持架面通风透光，雨前雨后加强巡查，降低高湿条件下的侵染机会。'),
  (20, '黑腐病严重', 'Grape Black Rot Fungus serious', '葡萄', 4, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现褐色圆斑并带黑色小点，果实可形成黑褐色凹陷斑，后期果粒干缩成僵果。', '建议优先处理重病叶、病果或病株，避免继续扩散。剪除病叶、病穗和僵果并带出园外处理；改善架面通风；雨季结合当地建议进行保护性防治。', '冬剪时清除病残体，保持架面通风透光，雨前雨后加强巡查，降低高湿条件下的侵染机会。'),
  (21, '轮斑病一般', 'Grape Black Measles Fungus general', '葡萄', 4, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现不规则褐色坏死斑，可能呈虎斑状或轮纹状，果实可出现褐色斑块、萎缩或品质下降。', '及时去除病叶病果，减少病原来源；加强水肥平衡和树势管理；必要时按登记范围选用适宜杀菌剂。', '避免植株长期处于弱势或水分胁迫状态，保持通风和合理负载，减少病害爆发条件。'),
  (22, '轮斑病严重', 'Grape Black Measles Fungus serious', '葡萄', 4, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现不规则褐色坏死斑，可能呈虎斑状或轮纹状，果实可出现褐色斑块、萎缩或品质下降。', '建议优先处理重病叶、病果或病株，避免继续扩散。及时去除病叶病果，减少病原来源；加强水肥平衡和树势管理；必要时按登记范围选用适宜杀菌剂。', '避免植株长期处于弱势或水分胁迫状态，保持通风和合理负载，减少病害爆发条件。'),
  (23, '褐斑病一般', 'Grape Leaf Blight Fungus general', '葡萄', 4, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶缘或叶片中部出现褐色坏死斑，病斑扩大后叶片干枯，严重时叶片大量脱落。', '摘除重病叶，保持园区通风降湿；发病初期可按当地植保建议进行杀菌剂防治。', '加强清园和水肥管理，避免密闭高湿，及时处理落叶病残体。'),
  (24, '褐斑病严重', 'Grape Leaf Blight Fungus serious', '葡萄', 4, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶缘或叶片中部出现褐色坏死斑，病斑扩大后叶片干枯，严重时叶片大量脱落。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除重病叶，保持园区通风降湿；发病初期可按当地植保建议进行杀菌剂防治。', '加强清园和水肥管理，避免密闭高湿，及时处理落叶病残体。'),
  (25, '健康', 'Citrus-Healthy', '柑桔', 5, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (26, '黄龙病一般', 'Citrus Greening June general', '柑桔', 5, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现不对称黄化斑驳，枝梢黄化，果实小而畸形、着色不均或味苦，植株逐渐衰弱。', '疑似病株应尽快请植保人员确认，重病株建议清除；重点防控柑橘木虱，避免带病苗木扩散。', '使用无病苗木，定期监测木虱和黄化症状，统一防控传毒媒介，及时清除确诊病株。'),
  (27, '黄龙病严重', 'Citrus Greening June serious', '柑桔', 5, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现不对称黄化斑驳，枝梢黄化，果实小而畸形、着色不均或味苦，植株逐渐衰弱。', '建议优先处理重病叶、病果或病株，避免继续扩散。疑似病株应尽快请植保人员确认，重病株建议清除；重点防控柑橘木虱，避免带病苗木扩散。', '使用无病苗木，定期监测木虱和黄化症状，统一防控传毒媒介，及时清除确诊病株。'),
  (28, '健康', 'Peach-Healthy', '桃', 6, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (29, '疮痂病一般', 'Peach_Bacterial Spot general', '桃', 6, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (30, '疮痂病严重', 'Peach_Bacterial Spot serious', '桃', 6, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (31, '健康', 'Pepper-Healthy', '辣椒', 7, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (32, '疮痂病一般', 'Pepper scab general', '辣椒', 7, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (33, '疮痂病严重', 'Pepper scab serious', '辣椒', 7, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (34, '健康', 'Potato-Healthy', '马铃薯', 8, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (35, '早疫病一般', 'Potato_Early Blight Fungus general', '马铃薯', 8, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。下部老叶先发病，出现褐色圆形或不规则病斑，常有同心轮纹，严重时叶片枯黄脱落。', '摘除病叶并减少田间湿度；发病初期可按当地植保建议选用适宜杀菌剂，注意交替用药。', '实行轮作，清除病残体，避免偏施氮肥，合理密植并保持植株通风。'),
  (36, '早疫病严重', 'Potato_Early Blight Fungus serious', '马铃薯', 8, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。下部老叶先发病，出现褐色圆形或不规则病斑，常有同心轮纹，严重时叶片枯黄脱落。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除病叶并减少田间湿度；发病初期可按当地植保建议选用适宜杀菌剂，注意交替用药。', '实行轮作，清除病残体，避免偏施氮肥，合理密植并保持植株通风。'),
  (37, '晚疫病一般', 'Potato_Late Blight Fungus general', '马铃薯', 8, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现水渍状暗绿色病斑，湿度大时叶背可见白色霉层，茎和果实也可迅速褐变腐烂。', '发现病株应尽快清除重病组织并降低湿度；病害扩展快时需及时采用当地推荐的登记药剂进行防控。', '避免连作，控制田间湿度和灌溉强度，雨季或低温高湿时期加强预警巡查。'),
  (38, '晚疫病严重', 'Potato_Late Blight Fungus serious', '马铃薯', 8, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现水渍状暗绿色病斑，湿度大时叶背可见白色霉层，茎和果实也可迅速褐变腐烂。', '建议优先处理重病叶、病果或病株，避免继续扩散。发现病株应尽快清除重病组织并降低湿度；病害扩展快时需及时采用当地推荐的登记药剂进行防控。', '避免连作，控制田间湿度和灌溉强度，雨季或低温高湿时期加强预警巡查。'),
  (39, '健康', 'Strawberry-Healthy', '草莓', 9, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (40, '叶枯病一般', 'Strawberry_Scorch general', '草莓', 9, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现紫褐色至褐色小斑，逐渐扩大并造成叶缘焦枯，严重时整片叶枯死。', '及时摘除老病叶，改善通风降湿；发病初期按当地植保建议选择适用杀菌剂。', '避免过密栽培和叶面长时间潮湿，清理病残体，合理施肥增强植株抗性。'),
  (41, '叶枯病严重', 'Strawberry_Scorch serious', '草莓', 9, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现紫褐色至褐色小斑，逐渐扩大并造成叶缘焦枯，严重时整片叶枯死。', '建议优先处理重病叶、病果或病株，避免继续扩散。及时摘除老病叶，改善通风降湿；发病初期按当地植保建议选择适用杀菌剂。', '避免过密栽培和叶面长时间潮湿，清理病残体，合理施肥增强植株抗性。'),
  (42, '健康', 'Tomato-Healthy', '番茄', 10, 'healthy', '植株整体长势正常，叶片颜色均匀，无明显斑点、霉层、坏死、卷曲或虫害损伤，果实与茎秆未见异常症状。', '当前无需特殊药剂处理。继续保持合理水肥、通风透光和田间巡查；如发现新病斑，应及时拍照复查并隔离疑似病叶。', '保持清洁田园，避免过密种植；根据作物需水需肥规律管理，定期观察叶片背面和新梢变化，减少病虫害早期扩散风险。'),
  (43, '白粉病一般', 'Tomato powdery mildew general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、嫩梢或果面出现白色粉状霉层，叶片可能卷曲、变脆，新梢生长受阻，严重时影响开花和结果。', '摘除重病叶和病梢；加强通风透光，降低湿度；可选用对白粉病有效且登记适用的药剂轮换防治。', '避免偏施氮肥和过密种植；保持植株通风，发病季节加强早期监测并及时处理初发病株。'),
  (44, '白粉病严重', 'Tomato powdery mildew serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、嫩梢或果面出现白色粉状霉层，叶片可能卷曲、变脆，新梢生长受阻，严重时影响开花和结果。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除重病叶和病梢；加强通风透光，降低湿度；可选用对白粉病有效且登记适用的药剂轮换防治。', '避免偏施氮肥和过密种植；保持植株通风，发病季节加强早期监测并及时处理初发病株。'),
  (45, '疮痂病一般', 'Tomato Bacterial Spot Bacteria general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (46, '疮痂病严重', 'Tomato Bacterial Spot Bacteria serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、果实或茎部出现水渍状小斑，随后形成褐色坏死斑或粗糙疮痂状斑点，严重时落叶落果。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除病叶病果，避免喷灌造成飞溅传播；可按作物登记范围选择铜制剂或其他适宜药剂，并注意安全间隔期。', '选用健康种苗，实行轮作，避免连作和过湿环境，雨后及时巡查并减少机械传播。'),
  (47, '早疫病一般', 'Tomato_Early Blight Fungus general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。下部老叶先发病，出现褐色圆形或不规则病斑，常有同心轮纹，严重时叶片枯黄脱落。', '摘除病叶并减少田间湿度；发病初期可按当地植保建议选用适宜杀菌剂，注意交替用药。', '实行轮作，清除病残体，避免偏施氮肥，合理密植并保持植株通风。'),
  (48, '早疫病严重', 'Tomato_Early Blight Fungus serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。下部老叶先发病，出现褐色圆形或不规则病斑，常有同心轮纹，严重时叶片枯黄脱落。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除病叶并减少田间湿度；发病初期可按当地植保建议选用适宜杀菌剂，注意交替用药。', '实行轮作，清除病残体，避免偏施氮肥，合理密植并保持植株通风。'),
  (49, '晚疫病一般', 'Tomato_Late Blight Water Mold general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现水渍状暗绿色病斑，湿度大时叶背可见白色霉层，茎和果实也可迅速褐变腐烂。', '发现病株应尽快清除重病组织并降低湿度；病害扩展快时需及时采用当地推荐的登记药剂进行防控。', '避免连作，控制田间湿度和灌溉强度，雨季或低温高湿时期加强预警巡查。'),
  (50, '晚疫病严重', 'Tomato_Late Blight Water Mold serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现水渍状暗绿色病斑，湿度大时叶背可见白色霉层，茎和果实也可迅速褐变腐烂。', '建议优先处理重病叶、病果或病株，避免继续扩散。发现病株应尽快清除重病组织并降低湿度；病害扩展快时需及时采用当地推荐的登记药剂进行防控。', '避免连作，控制田间湿度和灌溉强度，雨季或低温高湿时期加强预警巡查。'),
  (51, '叶霉病一般', 'Tomato_Leaf Mold Fungus general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。番茄叶片正面出现淡黄色斑块，叶背产生灰褐色或橄榄色霉层，严重时叶片卷曲枯死。', '加强通风排湿，摘除病叶；设施栽培应控制湿度，必要时按登记范围使用针对叶霉病的药剂。', '温室保持通风，避免夜间高湿，定期清除老叶和病残体，选择抗病品种。'),
  (52, '叶霉病严重', 'Tomato_Leaf Mold Fungus serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。番茄叶片正面出现淡黄色斑块，叶背产生灰褐色或橄榄色霉层，严重时叶片卷曲枯死。', '建议优先处理重病叶、病果或病株，避免继续扩散。加强通风排湿，摘除病叶；设施栽培应控制湿度，必要时按登记范围使用针对叶霉病的药剂。', '温室保持通风，避免夜间高湿，定期清除老叶和病残体，选择抗病品种。'),
  (53, '斑点病一般', 'Tomato Target Spot Bacteria general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片、茎或果实出现褐色圆形斑点，病斑常有黄色晕圈，果面斑点可能影响商品性。', '清除病叶病果，减少雨水飞溅传播；必要时按作物和病害登记范围进行药剂防控。', '使用健康种苗，实行轮作，控制田间湿度，农事操作避免带菌传播。'),
  (54, '斑点病严重', 'Tomato Target Spot Bacteria serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片、茎或果实出现褐色圆形斑点，病斑常有黄色晕圈，果面斑点可能影响商品性。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除病叶病果，减少雨水飞溅传播；必要时按作物和病害登记范围进行药剂防控。', '使用健康种苗，实行轮作，控制田间湿度，农事操作避免带菌传播。'),
  (55, '斑枯病一般', 'Tomato_Septoria Leaf Spot Fungus general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片上出现许多小型圆形灰白至褐色斑点，常有深色边缘和小黑点，严重时叶片枯黄脱落。', '摘除病叶并清理下部老叶，改善通风；发病初期可按当地植保建议进行防治。', '轮作换茬，避免高湿密植，清洁田园，减少病残体带菌。'),
  (56, '斑枯病严重', 'Tomato_Septoria Leaf Spot Fungus serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片上出现许多小型圆形灰白至褐色斑点，常有深色边缘和小黑点，严重时叶片枯黄脱落。', '建议优先处理重病叶、病果或病株，避免继续扩散。摘除病叶并清理下部老叶，改善通风；发病初期可按当地植保建议进行防治。', '轮作换茬，避免高湿密植，清洁田园，减少病残体带菌。'),
  (57, '红蜘蛛损伤一般', 'Tomato Spider Mite Damage general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现细小黄白色失绿点，叶背可见螨体或细网，严重时叶片发黄、干枯并影响结果。', '清除重害叶，增加田间湿度但避免病害高湿；保护天敌，虫口密度高时按标签选用登记杀螨剂。', '定期检查叶背，避免高温干旱环境长期持续，合理轮换药剂以降低抗性风险。'),
  (58, '红蜘蛛损伤严重', 'Tomato Spider Mite Damage serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。叶片出现细小黄白色失绿点，叶背可见螨体或细网，严重时叶片发黄、干枯并影响结果。', '建议优先处理重病叶、病果或病株，避免继续扩散。清除重害叶，增加田间湿度但避免病害高湿；保护天敌，虫口密度高时按标签选用登记杀螨剂。', '定期检查叶背，避免高温干旱环境长期持续，合理轮换药剂以降低抗性风险。'),
  (59, '黄化曲叶病毒病一般', 'Tomato YLCV Virus general', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。番茄新叶黄化、变小并向上卷曲，节间缩短，植株矮化，开花结果减少。', '病毒病无特效治疗药剂。及时拔除重病株，重点防控烟粉虱等传毒媒介，避免病株成为传染源。', '选用抗病品种和健康种苗，覆盖防虫网或诱虫板，控制粉虱，苗期和定植初期加强监测。'),
  (60, '黄化曲叶病毒病严重', 'Tomato YLCV Virus serious', '番茄', 10, 'serious', '当前识别为严重程度较高，病斑数量多或扩展较快。番茄新叶黄化、变小并向上卷曲，节间缩短，植株矮化，开花结果减少。', '建议优先处理重病叶、病果或病株，避免继续扩散。病毒病无特效治疗药剂。及时拔除重病株，重点防控烟粉虱等传毒媒介，避免病株成为传染源。', '选用抗病品种和健康种苗，覆盖防虫网或诱虫板，控制粉虱，苗期和定植初期加强监测。'),
  (61, '花叶病毒病', 'Tomato Tomv', '番茄', 10, 'general', '当前识别为一般程度，病斑或异常症状处于可观察和早期干预阶段。叶片出现黄绿相间的花叶、斑驳或畸形，新叶变小，植株可能矮化，严重时影响产量和品质。', '病毒病无特效治疗药剂。发现重病株应及时拔除或隔离，重点控制蚜虫、粉虱等传播媒介，并加强田间卫生。', '选用健康种苗和抗病品种，防治传毒昆虫，工具消毒，避免接触传播和病株残体再传播。')
